{"content":"// Port thief: simulates the hostile ambient CI runner for gh-1528 repro.
// Tight-loops binding ephemeral loopback ports, releasing them, and trying
// to re-grab the just-freed number — exactly the window the old test's
// freePort() -> re-bind pattern leaves open.
import 'dart:io';

Future<void> main(List<String> args) async {
  final seconds = args.isEmpty ? 60 : int.parse(args.first);
  final stop = DateTime.now().add(Duration(seconds: seconds));
  final held = <ServerSocket>[];
  var grabs = 0;
  while (DateTime.now().isBefore(stop)) {
    ServerSocket probe;
    try {
      probe = await ServerSocket.bind(InternetAddress.loopbackIPv4, 0);
    } on Object {
      continue;
    }
    final port = probe.port;
    await probe.close();
    try {
      final grab = await ServerSocket.bind(InternetAddress.loopbackIPv4, port);
      held.add(grab);
      grabs++;
    } on Object {
      // lost the race — victim got it first
    }
    while (held.length > 16) {
      await held.removeAt(0).close();
    }
  }
  for (final s in held) {
    await s.close();
  }
  stderr.writeln('thief done, stole $grabs ephemeral ports');
}
